const ARGUS_HTML="<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"ARGUS Protocol — HeartAI, laboratório de inteligência artificial autoral no The Workshop.\"><title>ARGUS / HeartAI — The Workshop</title>\n<style>\n:root{color-scheme:dark;--bg:#080b0e;--fg:#e9edea;--mut:#9ba7a6;--line:#283337;--a:#bbd9ca;--surface:#10181b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}a{color:inherit;text-decoration:none}a:hover{color:var(--a)}button,textarea{font:inherit}header{display:flex;justify-content:space-between;align-items:center;padding:23px max(5%,calc((100vw - 1160px)/2));border-bottom:1px solid var(--line);letter-spacing:.12em;font-size:12px}nav{display:flex;gap:25px}main{max-width:1160px;margin:auto;padding:0 5% 80px}.eye{color:var(--a);font-size:12px;letter-spacing:.2em;text-transform:uppercase}.hero{padding:95px 0 70px;border-bottom:1px solid var(--line)}h1{font-size:clamp(58px,11vw,135px);letter-spacing:-.085em;line-height:.92;margin:18px 0;font-weight:800}h1 span{color:var(--a)}.lede{max-width:700px;color:var(--mut);font-size:17px}.pills{display:flex;flex-wrap:wrap;gap:10px;margin:30px 0}.pill{border:1px solid #38474a;padding:5px 10px;font-size:11px;letter-spacing:.1em;color:var(--a)}.cta{display:inline-block;background:var(--a);color:#07100c;padding:13px 20px;font-weight:bold;margin-top:16px}.section{padding:64px 0;border-bottom:1px solid var(--line)}h2{font-size:clamp(26px,4vw,39px);line-height:1.15;margin:14px 0 30px}h3{font-size:17px;margin:10px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{padding:24px;background:var(--surface);border:1px solid var(--line);min-height:158px}.card p,.small{font-size:13px;color:var(--mut)}.index{color:var(--a);font-size:12px}.timeline{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.step{display:flex;gap:15px;border:1px solid var(--line);padding:17px}.status{margin-left:auto;white-space:nowrap;color:var(--mut);font-size:11px}.status.done{color:var(--a)}.play{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:var(--surface);border:1px solid var(--line);padding:22px}textarea{width:100%;min-height:140px;background:#080e10;color:var(--fg);border:1px solid #344346;padding:15px;resize:vertical;outline-color:var(--a)}pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font-size:13px;color:var(--a);min-height:80px}footer{padding:30px 5%;display:flex;justify-content:space-between;color:var(--mut);font-size:11px;gap:20px}code{color:var(--a)}@media(max-width:760px){.grid,.timeline,.play{grid-template-columns:1fr}header{padding:18px 5%}nav{gap:10px}.hero{padding:60px 0 45px}.status{font-size:10px}}\n</style></head>\n<body><header><a href=\"https://workshop-labs.pages.dev/\">W / THE WORKSHOP</a><nav><a href=\"#architecture\">ARQUITETURA</a><a href=\"#experiments\">EXPERIMENTOS</a><a href=\"#playground\">PLAYGROUND</a><a href=\"https://github.com/kingmaker-lab/The-Workshop./tree/main/IA/Heart\" rel=\"noopener noreferrer\">GITHUB ↗</a></nav></header>\n<main><section class=\"hero\"><div class=\"eye\">THE WORKSHOP / ARGUS PROTOCOL / PROJECT_001</div><h1>HEART<span>AI.</span></h1><p class=\"lede\">Construindo inteligência a partir dos fundamentos. Um laboratório de redes neurais, linguagem, memória e sistemas autônomos locais — código aberto para inspeção, experimentos reproduzíveis e nenhuma API externa de inferência.</p><div class=\"pills\"><span class=\"pill\">PYTHON 3.11+</span><span class=\"pill\">LOCAL FIRST</span><span class=\"pill\">NEURAL RESEARCH</span><span class=\"pill\">TEXT ONLY</span><span class=\"pill\">GENESIS / v0.1</span></div><a class=\"cta\" href=\"#playground\">EXPLORAR LABORATÓRIO ↗</a></section>\n<section class=\"section\" id=\"architecture\"><div class=\"eye\">01 / SYSTEM ARCHITECTURE</div><h2>Uma inteligência, construída em camadas.</h2><div class=\"grid\"><div class=\"card\"><span class=\"index\">01 / MEMORY</span><h3>Persistent context</h3><p>Histórico conversacional e eventos persistidos localmente em SQLite, isolados por sessão.</p></div><div class=\"card\"><span class=\"index\">02 / LANGUAGE</span><h3>Byte-level BPE</h3><p>Tokenizer autoral, treinamento local de merges e reversibilidade de texto UTF-8.</p></div><div class=\"card\"><span class=\"index\">03 / NEURAL</span><h3>HeartLM</h3><p>Pesquisa planejada: embeddings, atenção causal, Transformer decoder e geração autoregressiva.</p></div><div class=\"card\"><span class=\"index\">04 / COGNITION</span><h3>Agent runtime</h3><p>Roteamento controlado de ferramentas, regras de intenção e contexto operacional.</p></div><div class=\"card\"><span class=\"index\">05 / SECURITY</span><h3>Defense in depth</h3><p>Execução com permissões, allowlists, confirmação de risco e auditoria.</p></div><div class=\"card\"><span class=\"index\">06 / INTERFACE</span><h3>CLI / GUI</h3><p>Primeiro o terminal; interface gráfica opcional, sem expor o ambiente operacional.</p></div></div></section>\n<section class=\"section\" id=\"experiments\"><div class=\"eye\">02 / RESEARCH LOG</div><h2>Diário dos experimentos.</h2><div class=\"timeline\" id=\"timeline\"></div><p class=\"small\">“Implementado” indica código publicado no repositório; não significa aprovação de todos os testes em produção. HeartLM ainda não é um LLM treinado.</p></section>\n<section class=\"section\" id=\"playground\"><div class=\"eye\">03 / INTERACTIVE LAB</div><h2>Tokenizer Playground.</h2><p class=\"small\">Demonstração didática de tokenização por bytes UTF-8, com merges BPE de exemplo calculados localmente. O vocabulário de produção do HeartAI não é carregado aqui. Nada é enviado ao servidor.</p><div class=\"play\"><div class=\"panel\"><h3>INPUT / UTF-8</h3><label for=\"input\" class=\"small\">Texto de entrada</label><textarea id=\"input\" maxlength=\"3000\" spellcheck=\"false\">Olá, HeartAI! 🦊</textarea><div class=\"small\" id=\"stats\"></div></div><div class=\"panel\"><h3>OUTPUT / BYTE-BPE DEMO</h3><pre id=\"output\" aria-live=\"polite\"></pre><div class=\"small\">IDs 0–255: bytes; 256–258: tokens especiais; IDs ≥259: merges aprendidos nesta demonstração.</div></div></div></section>\n<section class=\"section\"><div class=\"eye\">04 / SOURCE CODE</div><h2>Build. Break. Understand. Rebuild.</h2><p class=\"lede\">Repositório único. Bancada independente. Documentação e código auditáveis.</p><a class=\"cta\" href=\"https://github.com/kingmaker-lab/The-Workshop./tree/main/IA/Heart\" rel=\"noopener noreferrer\">VER HEARTAI NO GITHUB ↗</a></section></main>\n<footer><span>© 2026 THE WORKSHOP — WOLFPACK / KINGMAKER</span><span>ARGUS PROTOCOL / HEARTAI / PROJECT_001</span></footer>\n<script src=\"/argus/argus.js\" defer></script></body></html>";
const ARGUS_JS="\"use strict\";\nconst experiments=[[\"HEART_001\",\"Runtime local\",\"IMPLEMENTADO\"],[\"HEART_002\",\"Memória conversacional\",\"IMPLEMENTADO\"],[\"HEART_003\",\"Byte-level BPE\",\"IMPLEMENTADO\"],[\"HEART_004\",\"Neural Embeddings\",\"PLANEJADO\"],[\"HEART_005\",\"Causal Attention\",\"PLANEJADO\"],[\"HEART_006\",\"Transformer Decoder\",\"PLANEJADO\"],[\"HEART_007\",\"Training & Backprop\",\"PLANEJADO\"],[\"HEART_008\",\"Autoregressive Inference\",\"PLANEJADO\"],[\"HEART_009\",\"Agent Planning\",\"PLANEJADO\"],[\"HEART_010\",\"Linux Sandbox Integration\",\"PLANEJADO\"]];\nconst timeline=document.getElementById(\"timeline\");\nfor(const [id,name,status] of experiments){const el=document.createElement(\"div\");el.className=\"step\";const nameEl=document.createElement(\"span\");nameEl.textContent=id+\" / \"+name;const s=document.createElement(\"span\");s.className=\"status\"+(status===\"IMPLEMENTADO\"?\" done\":\"\");s.textContent=status;el.append(nameEl,s);timeline.append(el)}\n// Exemplo restrito e transparente: aprende merges somente a partir de um pequeno corpus público fixo.\nconst te=new TextEncoder();const corpus=[\"heartai heartai heartai\",\"neural neural neural\",\"inteligencia inteligencia\",\"heart heart heart\",\"token token token\"];\nlet sequences=corpus.map(s=>Array.from(te.encode(s)));const merges=[];\nfor(let id=259;id<287;id++){const counts=new Map();for(const s of sequences){for(let i=0;i<s.length-1;i++){const k=s[i]+\",\"+s[i+1];counts.set(k,(counts.get(k)||0)+1)}}const ranked=[...counts].filter(([,n])=>n>=2).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));if(!ranked.length)break;const pair=ranked[0][0].split(\",\").map(Number);merges.push(pair);sequences=sequences.map(s=>merge(s,pair,id))}\nfunction merge(ids,p,id){const out=[];for(let i=0;i<ids.length;i++){if(i+1<ids.length&&ids[i]===p[0]&&ids[i+1]===p[1]){out.push(id);i++}else out.push(ids[i])}return out}\nfunction encode(s){let ids=Array.from(te.encode(s));merges.forEach((pair,i)=>{ids=merge(ids,pair,259+i)});return ids}\nconst input=document.getElementById(\"input\"),output=document.getElementById(\"output\"),stats=document.getElementById(\"stats\");function render(){const raw=Array.from(te.encode(input.value));const tokens=encode(input.value);output.textContent=JSON.stringify(tokens);stats.textContent=\"CARACTERES: \"+[...input.value].length+\"  /  BYTES: \"+raw.length+\"  /  TOKENS: \"+tokens.length+\"  /  MERGES DEMO: \"+merges.length}input.addEventListener(\"input\",render);render();\n";
const SITE_PAGES = new Map([
  ["/", HUB_HTML],
  ["/argus", ARGUS_HTML],
  ["/argus/heartai", ARGUS_HTML],
  ["/projects/argus", ARGUS_HTML],
  ["/projects/wolf-vm", WOLF_HTML],
  ["/wolf-vm", WOLF_HTML],
  ["/projects/ares", HTML],
  ["/ares", HTML],
  ["/projects/ares/tcp-foundation", TCP_HTML],
  ["/ares/tcp-foundation", TCP_HTML],
  ["/projects/ares/http-parser", HTTP_HTML],
  ["/ares/http-parser", HTTP_HTML],
  ["/projects/ares/responses-routing", SERVER_HTML],
  ["/ares/responses-routing", SERVER_HTML],
  ["/projects/ares/static-files", STATIC_HTML],
  ["/ares/static-files", STATIC_HTML]
]);

export default {
  async fetch(request) {
    const method = request.method.toUpperCase();
    if (method !== "GET" && method !== "HEAD") {
      return new Response(method === "HEAD" ? null : "405 Method Not Allowed", {
        status: 405,
        headers: {...security, "Allow":"GET, HEAD",
          "Content-Type":"text/plain; charset=utf-8", "Cache-Control":"no-store"}
      });
    }
    const path = new URL(request.url).pathname.replace(/\/+$/, "") || "/";
    const output = (body, contentType, cacheSeconds = 120) =>
      new Response(method === "HEAD" ? null : body, {
        status: 200, headers: {
          ...security, "Content-Type":contentType,
          "Cache-Control":"public, max-age=" + cacheSeconds
        }
      });
    const assets = new Map([
      ["/assets/hub.css", [HUB_CSS,"text/css; charset=utf-8"]],
      ["/argus/argus.js", [ARGUS_JS,"application/javascript; charset=utf-8"]],
      ["/assets/ares.css", [CSS,"text/css; charset=utf-8"]],
      ["/assets/ares.js", [JS,"application/javascript; charset=utf-8"]],
      ["/assets/tcp.css", [TCP_CSS,"text/css; charset=utf-8"]],
      ["/assets/http-parser.css", [HTTP_CSS,"text/css; charset=utf-8"]],
      ["/favicon.svg", [ICON,"image/svg+xml; charset=utf-8"]]
    ]);
    if (assets.has(path)) {
      const [content, type] = assets.get(path);
      return output(content, type, 3600);
    }
    if (path === "/projects/crypto" || path === "/crypto" ||
        path === "/crypto-labs") {
      return new Response(null, {
        status: 302,
        headers: {...security, "Location":"https://wolfpack-crypto.pages.dev/",
          "Cache-Control":"public, max-age=300"}
      });
    }
    if (SITE_PAGES.has(path))
      return output(SITE_PAGES.get(path), "text/html; charset=utf-8");
    return new Response(method === "HEAD" ? null : "404 — Not Found", {
      status: 404,
      headers: {...security, "Content-Type":"text/plain; charset=utf-8",
        "Cache-Control":"no-store"}
    });
  }
};
